update public.case_questions set prompt='Concept Check stores learners.last_case_result, updated after each new case. A learner fails the first case, gets the follow-up, then passes the second case. How many case results can the database show?', answer_core='1', aliases='["1","one"]'::jsonb, required_groups=null, patterns='[]'::jsonb, answer_reason='Only the latest result is stored: the second case’s pass overwrote the first case’s fail.' where id=26 and concept_id=6 and prompt like '%last_case_result%';
